<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/config.php';require_once ROOT_PATH.'/security/middleware/AuthMiddleware.php';require_once ROOT_PATH.'/services/LearningToolsService.php';
header('Content-Type: application/json');header('Cache-Control: no-store');$u=AuthMiddleware::requireAuth(true);$fac=($_GET['mode']??'student')==='facilitator';
if(!in_array($u['role']??'',$fac?['facilitator','admin','super_admin','moderator']:['student','facilitator','admin','super_admin','moderator'],true)){http_response_code(403);echo json_encode(['error'=>'Dashboard access denied']);exit;}
$method=$_SERVER['REQUEST_METHOD'];if(!in_array($method,['GET','POST'],true)){http_response_code(405);exit;}if($method==='POST')AuthMiddleware::verifyCsrf();session_write_close();
try{$s=new LearningToolsService();$action=(string)($_GET['action']??'profile');if($method==='POST'){$b=json_decode(file_get_contents('php://input'),true,32,JSON_THROW_ON_ERROR);if(!is_array($b))throw new InvalidArgumentException('Invalid request.');$data=$s->mutate((int)$u['id'],$fac,$action,$b);if($action==='profile'){AuthMiddleware::startSession();$_SESSION['full_name']=$data['full_name'];session_write_close();}}else $data=$s->transport($s->view((int)$u['id'],$fac,$action,(int)($_GET['server_id']??0)));echo json_encode(['success'=>true,'data'=>$data],JSON_THROW_ON_ERROR|JSON_INVALID_UTF8_SUBSTITUTE);}
catch(InvalidArgumentException|JsonException $e){http_response_code(422);echo json_encode(['error'=>$e->getMessage()]);}catch(Throwable $e){$c=in_array($e->getCode(),[403,404,409],true)?$e->getCode():503;http_response_code($c);if($c===503)error_log('[Learning tools] '.$e->getMessage());echo json_encode(['error'=>$c===503?'Learning tool data is temporarily unavailable.':$e->getMessage()]);}
